"""Connected accounts, durable jobs, finding history, preferences and retention.

Removes only repositories explicitly marked as bundled fixtures in revision 001.
Back up the database before upgrading; fixture deletion is intentionally irreversible.
"""
from alembic import op
import sqlalchemy as sa
import json
from uuid import uuid4
from datetime import datetime, timedelta

revision = "002"
down_revision = "001"
branch_labels = None
depends_on = None


def upgrade():
    db = op.get_bind()
    # These rows were generated by the removed demo flow, never imported user source.
    db.execute(sa.text('DELETE FROM review WHERE scan_id IN (SELECT s.id FROM scan s JOIN repository r ON r.id=s.repository_id WHERE r.is_fixture = true)'))
    db.execute(sa.text('UPDATE scan SET baseline_id = NULL WHERE baseline_id IN (SELECT s.id FROM scan s JOIN repository r ON r.id=s.repository_id WHERE r.is_fixture = true)'))
    db.execute(sa.text('DELETE FROM scan WHERE repository_id IN (SELECT id FROM repository WHERE is_fixture = true)'))
    db.execute(sa.text('DELETE FROM repository WHERE is_fixture = true'))
    with op.batch_alter_table("user") as batch:
        batch.alter_column("github_id", existing_type=sa.Integer(), type_=sa.BigInteger(), existing_nullable=False)
        batch.add_column(sa.Column("encrypted_refresh_token", sa.String(), nullable=False, server_default=""))
        batch.add_column(sa.Column("token_expires_at", sa.DateTime()))
        batch.add_column(sa.Column("avatar_url", sa.String(), nullable=False, server_default=""))
        batch.add_column(sa.Column("created_at", sa.DateTime(), nullable=False, server_default=sa.func.now()))
    op.create_table("installation",
        sa.Column("id", sa.String(), primary_key=True), sa.Column("owner_id", sa.String(), sa.ForeignKey("user.id"), nullable=False),
        sa.Column("github_id", sa.BigInteger(), nullable=False), sa.Column("account", sa.String(), nullable=False),
        sa.Column("account_type", sa.String(), nullable=False), sa.Column("permissions", sa.JSON(), nullable=False),
        sa.Column("status", sa.String(), nullable=False), sa.Column("synced_at", sa.DateTime(), nullable=False),
        sa.UniqueConstraint("owner_id", "github_id", name="uq_installation_owner_github"))
    with op.batch_alter_table("repository") as batch:
        batch.drop_column("is_fixture")
        batch.alter_column("github_id", existing_type=sa.Integer(), type_=sa.BigInteger())
        batch.alter_column("installation_id", existing_type=sa.Integer(), type_=sa.BigInteger())
        for name, default in [("visibility", "private"), ("language", ""), ("github_updated_at", ""), ("connection_status", "connected")]:
            batch.add_column(sa.Column(name, sa.String(), nullable=False, server_default=default))
        batch.add_column(sa.Column("synced_at", sa.DateTime()))
        batch.add_column(sa.Column("auto_scan", sa.Boolean(), nullable=False, server_default=sa.false()))
        batch.add_column(sa.Column("schedule_hours", sa.Integer(), nullable=False, server_default="0"))
        batch.add_column(sa.Column("next_scan_at", sa.DateTime()))
        batch.add_column(sa.Column("checks_enabled", sa.Boolean(), nullable=False, server_default=sa.false()))
        batch.add_column(sa.Column("blocking_checks", sa.Boolean(), nullable=False, server_default=sa.false()))
    # Repair historical dangling comparison IDs before enforcing referential integrity.
    db.execute(sa.text('UPDATE scan SET baseline_id=NULL WHERE baseline_id IS NOT NULL AND baseline_id NOT IN (SELECT id FROM scan)'))
    with op.batch_alter_table("scan") as batch:
        batch.create_foreign_key("fk_scan_baseline", "scan", ["baseline_id"], ["id"])
        for name, default in [("branch", "main"), ("trigger", "manual"), ("encrypted_source", ""), ("base_commit", "")]:
            batch.add_column(sa.Column(name, sa.String(), nullable=False, server_default=default))
        batch.add_column(sa.Column("job_key", sa.String()))
        batch.add_column(sa.Column("attempts", sa.Integer(), nullable=False, server_default="0"))
        for name in ["queued_at", "started_at", "heartbeat_at", "source_expires_at"]:
            batch.add_column(sa.Column(name, sa.DateTime()))
        batch.add_column(sa.Column("publish_check", sa.Boolean(), nullable=False, server_default=sa.false()))
        batch.add_column(sa.Column("changed_files", sa.JSON(), nullable=False, server_default="[]"))
        batch.create_index("ix_scan_job_key", ["job_key"], unique=True)
    db.execute(sa.text('UPDATE scan SET branch = (SELECT branch FROM repository WHERE repository.id = scan.repository_id)'))
    op.create_table("repositorybranch",
        sa.Column("id", sa.String(), primary_key=True), sa.Column("repository_id", sa.String(), sa.ForeignKey("repository.id"), nullable=False),
        sa.Column("name", sa.String(), nullable=False), sa.Column("commit_sha", sa.String(), nullable=False), sa.Column("synced_at", sa.DateTime(), nullable=False),
        sa.UniqueConstraint("repository_id", "name", name="uq_repositorybranch_repository_name"))
    op.create_table("findingrecord",
        sa.Column("id", sa.String(), primary_key=True), sa.Column("repository_id", sa.String(), sa.ForeignKey("repository.id"), nullable=False),
        sa.Column("branch", sa.String(), nullable=False), sa.Column("fingerprint", sa.String(), nullable=False),
        sa.Column("first_seen", sa.DateTime(), nullable=False), sa.Column("last_seen", sa.DateTime(), nullable=False), sa.Column("resolved_at", sa.DateTime()),
        sa.Column("status", sa.String(), nullable=False), sa.Column("note", sa.String(), nullable=False),
        sa.Column("latest_scan_id", sa.String(), sa.ForeignKey("scan.id"), nullable=False), sa.Column("evidence", sa.JSON(), nullable=False),
        sa.UniqueConstraint("repository_id", "branch", "fingerprint", name="uq_findingrecord_repository_branch_fingerprint"))
    op.create_table("aianalysis",
        sa.Column("id", sa.String(), primary_key=True), sa.Column("scan_id", sa.String(), sa.ForeignKey("scan.id"), nullable=False),
        sa.Column("fingerprint", sa.String(), nullable=False), sa.Column("provider", sa.String(), nullable=False),
        sa.Column("result", sa.JSON(), nullable=False), sa.Column("created_at", sa.DateTime(), nullable=False))
    op.create_table("vulnerabilityreference", sa.Column("id", sa.String(), primary_key=True), sa.Column("payload", sa.JSON(), nullable=False), sa.Column("expires_at", sa.DateTime(), nullable=False))
    op.create_table("userpreference", sa.Column("user_id", sa.String(), sa.ForeignKey("user.id"), primary_key=True), sa.Column("notify_scan_failure", sa.Boolean(), nullable=False), sa.Column("notify_high_findings", sa.Boolean(), nullable=False))
    op.create_table("notification",
        sa.Column("id", sa.String(), primary_key=True), sa.Column("user_id", sa.String(), sa.ForeignKey("user.id"), nullable=False),
        sa.Column("scan_id", sa.String(), sa.ForeignKey("scan.id"), nullable=False), sa.Column("message", sa.String(), nullable=False),
        sa.Column("read", sa.Boolean(), nullable=False), sa.Column("created_at", sa.DateTime(), nullable=False))
    op.create_table("workerhealth", sa.Column("id", sa.String(), primary_key=True), sa.Column("heartbeat_at", sa.DateTime(), nullable=False))
    for table, column in [("installation", "owner_id"), ("installation", "github_id"), ("repositorybranch", "repository_id"), ("findingrecord", "repository_id"), ("findingrecord", "fingerprint"), ("aianalysis", "scan_id"), ("notification", "user_id")]:
        op.create_index(f"ix_{table}_{column}", table, [column])
    # Preserve imported evidence and review decisions from revision 001.
    records = {}
    scans = db.execute(sa.text("SELECT id, repository_id, branch, findings, coverage, created_at, completed_at FROM scan WHERE status IN ('completed','partial') ORDER BY created_at, id")).mappings()
    for scan in scans:
        findings = json.loads(scan["findings"]) if isinstance(scan["findings"], str) else scan["findings"]
        coverage = json.loads(scan["coverage"]) if isinstance(scan["coverage"], str) else scan["coverage"]
        stamp = scan["completed_at"] or scan["created_at"]
        current = set()
        for finding in findings:
            fingerprint = finding.get("fingerprint")
            if not fingerprint: continue
            key = (scan["repository_id"], scan["branch"], fingerprint)
            current.add(key)
            review = db.execute(sa.text("SELECT status, note FROM review WHERE scan_id=:scan AND fingerprint=:fingerprint ORDER BY updated_at DESC"), {"scan": scan["id"], "fingerprint": fingerprint}).mappings().first()
            previous = records.get(key)
            records[key] = {"id": previous["id"] if previous else str(uuid4()), "repository_id": key[0], "branch": key[1], "fingerprint": fingerprint,
                "first_seen": previous["first_seen"] if previous else stamp, "last_seen": stamp, "resolved_at": None,
                "status": review["status"] if review else previous["status"] if previous else "open", "note": review["note"] if review else previous["note"] if previous else "",
                "latest_scan_id": scan["id"], "evidence": finding}
        if coverage.get("complete"):
            for key, record in records.items():
                if key[:2] == (scan["repository_id"], scan["branch"]) and key not in current and record["resolved_at"] is None: record["resolved_at"] = stamp
    table = sa.Table("findingrecord", sa.MetaData(), autoload_with=db)
    for record in records.values():
        for field in ("first_seen", "last_seen", "resolved_at"):
            if isinstance(record[field], str): record[field] = datetime.fromisoformat(record[field])
        db.execute(table.insert().values(**record))
    # Old snapshots predate retention timestamps. Purge their source now; keep findings.
    db.execute(sa.text("UPDATE scan SET files='{}', encrypted_source=''"))
    db.execute(sa.text("UPDATE scan SET status='failed', error='Worker state predates upgrade; retry the scan' WHERE status IN ('queued','running')"))
    op.create_index("ix_scan_repository_created", "scan", ["repository_id", "created_at"])
    op.create_index("ix_scan_status_heartbeat", "scan", ["status", "heartbeat_at"])
    op.create_index("ix_auditevent_user_created", "auditevent", ["user_id", "created_at"])


def downgrade():
    # Data destructive down migrations would remove actual findings and user preferences.
    # Restore a pre-upgrade backup instead of silently discarding those records.
    raise RuntimeError("Revision 002 is forward-only. Restore the pre-upgrade backup to roll back.")
